        LANGUAGE_WRAPPER = 'In a $d$-dimensional geometry problem, a set of $d+1$ positive numbers $R_0, R_1, \\dots, R_d$ arises from the ratios of segments along cevians in a $d$-simplex. These numbers are known to satisfy the property $\\sum_{i=0}^d \\frac{1}{R_i+1} = 1$. Suppose that for a particular instance of these ratios and a constant $c={c}$, it is calculated that \\[\n\\sum_{i=0}^d \\frac{1}{R_i+c} = {K_str}\n\\] Find the value of the expression \\[\n\\sum_{i=0}^d \\frac{R_i^2}{(R_i+1)(R_i+c)}\n\\] Express your answer as a fraction in simplest form.'

        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        from fractions import Fraction

def generator(rng):
    d = rng.randint(2, 5)
    c = rng.choice([i for i in range(-3, 6) if i != 0]) # c=0 is trivial, c=1 is special case handled by formula

    # Generate a_i > 1 such that sum(1/a_i) = 1
    # Start with a_list for d=1, which is [2, 2]
    a_list = [Fraction(2), Fraction(2)]
    for _ in range(d - 1):
        # To increase dimension by 1, apply the splitting rule 1/n = 1/(n+1) + 1/(n*(n+1))
        # We pick the largest element to split to keep numbers smaller
        a_list.sort()
        m = a_list.pop(-1)
        a_list.append(m + 1)
        a_list.append(m * (m + 1))

    R = [a - 1 for a in a_list]

    # Ensure c is not -R_i for any i
    for r_val in R:
        if r_val + c == 0:
            # This is rare, but possible if c is negative. Retry.
            return generator(rng)

    # Calculate K
    K = sum((Fraction(1, r + c) for r in R), Fraction(0))

    # Calculate the answer P
    if c == 1:
        P = d - 1 + K
    else:
        P_num = (d + 1) * (c - 1) + 1 - c**2 * K
        P_den = c - 1
        P = Fraction(P_num, P_den)

    K_str = str(K.numerator)
    if K.denominator != 1:
        K_str += f"/{K.denominator}"

    return {
        'd': d,
        'c': c,
        'K_str': K_str,
        'K_num': K.numerator,
        'K_den': K.denominator,
        'ans_num': P.numerator,
        'ans_den': P.denominator
    }

        from fractions import Fraction

def verifier(assign):
    d = assign['d']
    c = assign['c']
    K = Fraction(assign['K_num'], assign['K_den'])

    # Validate constraints
    if not (2 <= d <= 5):
        # Dimension out of expected range
        return False, None
    if c == 0:
        # c=0 makes the problem trivial
        return False, None

    # Recompute the answer
    if c == 1:
        # Special case for c=1
        P = d - 1 + K
    else:
        # General case for c != 1
        P_num = (d + 1) * (c - 1) + 1 - c**2 * K
        P_den = c - 1
        if P_den == 0:
            # Should not happen if c!=1
            return False, None
        P = Fraction(P_num, P_den)

    # Check if the computed answer matches the expected answer
    if P.numerator == assign['ans_num'] and P.denominator == assign['ans_den']:
        return True, f"{P.numerator}/{P.denominator}"
    else:
        # Mismatch between generator and verifier logic
        return False, None


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
